<script setup lang="ts">
import {computed,onBeforeUnmount,ref,watch} from 'vue';
import {onBeforeRouteLeave} from 'vue-router';

import {useI18n} from '@vben/locales';

import {AcademicError,type AdminEntry,type BatchPreview,type BatchRequest,call,type Decision,Mutation,type Task} from './api';
const props=defineProps<{disabled:boolean;tasks:Task[];}>();const emit=defineEmits<{changed:[];pending:[value:boolean]}>();const {t}=useI18n();
const selected=ref<string[]>([]);const action=ref<Decision['action']>('hide');const reason=ref('');const preview=ref<BatchPreview>();const request=ref<BatchRequest>();const busy=ref(false);const uncertain=ref(false);const error=ref('');const mutation=new Mutation();
const dirty=computed(()=>selected.value.length>0||reason.value.length>0);watch([selected,action,reason],()=>{preview.value=undefined;request.value=undefined},{deep:true});watch([busy,uncertain,dirty],()=>emit('pending',busy.value||uncertain.value||dirty.value));onBeforeUnmount(()=>emit('pending',false));onBeforeRouteLeave(()=>!(busy.value||uncertain.value||dirty.value)||window.confirm(t('page.academic.unsavedChanges')));
async function inspect(){if(busy.value)return;busy.value=true;error.value='';try{const items:BatchRequest['items']=[];for(const id of selected.value){const task=props.tasks.find(item=>item.id===id);if(!task)throw new AcademicError('conflict');const entry=await call<AdminEntry>('reviews',`/admin/entries/${encodeURIComponent(task.submission.object_id)}`,'AdminEntry');items.push({id,revision:task.revision,decision:{id:'',object_id:entry.id,revision:entry.revision,action:action.value,reason:reason.value}})};const value={items,preview_token:''};preview.value=await call<BatchPreview>('moderation','/tasks/batch-preview','BatchPreview',{body:value,key:crypto.randomUUID()});request.value={...value,preview_token:preview.value.preview_token}}catch(error_){error.value=error_ instanceof AcademicError?error_.code:'unavailable'}finally{busy.value=false}}
async function apply(){if(!request.value||busy.value)return;busy.value=true;error.value='';try{preview.value=await mutation.run<BatchPreview>('moderation','/tasks/batch','BatchPreview',request.value);emit('changed')}catch(error_){error.value=error_ instanceof AcademicError?error_.code:'unavailable'}finally{busy.value=false;uncertain.value=mutation.uncertain}}
function reset(){selected.value=[];reason.value='';preview.value=undefined;request.value=undefined}
</script>
<template><details class="admin-form"><summary>{{ t('page.academic.batchTitle') }}</summary><fieldset :disabled="disabled || busy || uncertain"><label v-for="task in tasks.filter(item=>item.state === 'waiting')" :key="task.id" class="checkbox"><input v-model="selected" type="checkbox" :value="task.id" :disabled="!selected.includes(task.id) && selected.length >= 20" />{{ t(`page.academic.requestKinds.${task.submission.kind}`) }} {{ task.submission.reason === 'content_review' ? t('page.academic.originalContent') : task.submission.reason }}</label><label>{{ t('page.academic.moderationAction') }}<select v-model="action"><option v-for="value in ['publish','hide','restore','delete','feature','unfeature','dismiss']" :key="value" :value="value">{{ t(`page.academic.actions.${value}`) }}</option></select></label><label>{{ t('page.academic.decisionReason') }}<textarea v-model="reason" maxlength="2000" rows="3"></textarea></label></fieldset><p v-if="error" role="alert">{{ t(`page.academic.errors.${error}`) }}</p><p v-if="uncertain">{{ t('page.academic.uncertain') }}</p><ul v-if="preview" class="admin-list"><li v-for="item in preview.items" :key="item.id">{{ item.id }} {{ t(`page.academic.operationStates.${item.state}`) }}<span v-if="item.code"> {{ t(`page.academic.errors.${item.code}`) }}</span></li></ul><div class="admin-actions"><button :disabled="disabled || busy || uncertain || selected.length === 0 || !reason.trim()" @click="inspect">{{ t('page.academic.previewBatch') }}</button><button v-if="request" :disabled="disabled || busy" @click="apply">{{ t(uncertain ? 'page.academic.retry' : 'page.academic.applyBatch') }}</button><button :disabled="busy || uncertain" @click="reset">{{ t('page.academic.cancel') }}</button></div></details></template>
